#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
union all SELECT count(1) as countNum, 'chbEqudet' as countType FROM CHB_EQUDET ce WHERE ce.STATUS='A'
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
union all SELECT count(1) as countNum, 'chbPrdresistCode' as countType FROM CHB_PRDRESIST_CODE cpc
WHERE (cpc.REG_CODE is NULL or cpc.REG_CODE = '')
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
